// ═══════════════════════════════════════════════════════════════
// City data. single source of truth for all birth-support pages
// ═══════════════════════════════════════════════════════════════

export interface HospitalDetail {
  name: string;
  address?: string;
  paragraph: string;
  thumbnail?: string;
  nicuLevel?: string;
  birthVolume?: string;           // e.g. "~4,500 births/year"
  vbacPolicy?: string;            // e.g. "Allows TOLAC/VBAC"
  doulaPolicy?: string;            // e.g. "Doulas welcome as support persons"
  midwifeFriendly?: boolean;       // CNM-attended births available
  waterBirth?: string;            // e.g. "Labor tubs available; water birth not routinely offered"
  medicaid?: boolean;              // Accepts Health First Colorado
  lactation?: boolean;             // IBCLCs on staff
  privateRooms?: boolean;          // Private L&D rooms
  url?: string;                    // Hospital maternity page URL
}

export interface BirthCenterDetail {
  name: string;
  address?: string;
  paragraph: string;
  thumbnail?: string;
  distance?: string;              // e.g. "45 miles from Denver" for centers outside the city
  credential?: string;            // e.g. "CABC Accredited" , "State Licensed"
  services?: string[];            // e.g. ["Water Birth" , "VBAC" , "Home Transfer"],
  costRange?: string;             // e.g. "$4,000–$6,000"
  medicaid?: boolean;             // Accepts Medicaid/Medicaid birth coverage
  url?: string;                   // Birth center website URL
  phone?: string;                  // Birth center phone number
  bilingual?: boolean;            // Bilingual services available
  midwives?: string[];            // List of midwife names
  description?: string;           // Full description (alternative to paragraph)
  isVerified?: boolean;          // Only true after provider confirms info via outreach
}

export interface FaqItem {
  q: string;
  a: string;
}

export interface Testimonial {
  quote: string;
  attribution: string;
  source: 'client' | 'doula' | 'midwife';
}

export interface LocalDoula {
  name: string;
  credential?: string;
  practice?: string;
  url?: string;
  description?: string;
  photo?: string;              // Path to headshot in /images/doulas/ (e.g. '/images/doulas/sonja-spitzer.webp')
  isAmbassador?: boolean;
  isMidwife?: boolean;
  isVerified?: boolean;        // Only true after provider confirms info via outreach
  costRange?: string;          // e.g. "$800–$1,200"
  serviceArea?: string[];      // e.g. ["Denver" , "Aurora" , "Lakewood"],
  acceptsMedicaid?: boolean;   // If true, show green "Accepts Medicaid" badge
  services?: string[];         // e.g. ["Birth Doula" , "Postpartum" , "Lactation"],
  acceptingClients?: boolean | string; // true = "Accepting clients" , false = hide, string = custom label
  /**
   * Stable unique identifier for this provider, e.g. "fremont-soul-sisters-doula-training-001".
   * Used as the link between cities.ts and the Google Sheet outreach tracker.
   * Pattern: {city-slug}-{name-slug}-{NNN}
   * Deterministic. does not change even if enrichment data changes.
   * Required for any provider that has been enriched or added to the Sheet.
   */
  id?: string;
  /**
   * Date (YYYY-MM-DD) when this provider was last enriched (data scraped, verified, added).
   * Used to prevent re-research: if enrichedAt is within 30 days, skip re-scraping.
   * If absent, the provider may not have been individually researched yet.
   */
  enrichedAt?: string;
  languages?: string[];           // e.g. ["Spanish", "ASL"]
  virtualConsultations?: boolean; // offers virtual consults
  slidingScale?: boolean;         // offers sliding scale pricing
  homeBirthSupport?: boolean;     // supports home births
  vbacSupportive?: boolean;       // explicitly supports VBAC clients
  waterBirthSupport?: boolean;    // offers water birth support
}

export interface CityData {
  city: string;
  state: string;
  slug: string;
  costLow: number;
  costHigh: number;
  shelbiServesHere: boolean;
  lat?: number;                // Required for GeoCoordinates schema
  lng?: number;                // Required for GeoCoordinates schema
  publishedDate?: string;      // YYYY-MM-DD for sitemap lastmod
  culture: string;
  heroLocalDetail: string;
  hospitalDetails: HospitalDetail[];
  birthCenterDetails: BirthCenterDetail[];
  localDoulas?: LocalDoula[];
  medicaidNote: string;
  insuranceNote: string;
  faqs: FaqItem[];
  nearbyCities: string[];
  testimonials?: Testimonial[];  // Real client quotes; if absent, show 'What local moms ask' Q&A
  enableBlogResources?: boolean;  // Show hero-image blog cards vs icon cards in Related Resources
  heroImage?: string;             // City-specific pregnant woman silhouette hero image (e.g. '/images/denver-co-birth-doula-hero-v2.webp')
  supportSceneImage?: string;     // City-specific support scene image (e.g. '/images/denver-support-scene.webp')
  supportSceneAlt?: string;       // City-specific support scene alt text
  costSectionImage?: string;      // City-specific cost section image
  insuranceSectionImage?: string; // City-specific insurance/medicaid section image
  midwifeSectionImage?: string;   // City-specific midwife section image
  ogImage?: string;               // City-specific OG image URL (e.g. 'https://truejoybirthing.com/images/og-city-denver-co.webp')
  midwifeInfo?: {                 // City-specific midwife section text (if absent, generic text is used)
    paragraph: string;            // Full midwife landscape paragraph
    credentialTypes: string;      // e.g. " and RMs" for CO, " and LMs" for WA, "" for generic
    credentialDetail: string;     // e.g. "In Colorado, Registered Midwives (RMs) are specifically licensed...",

  };
  birthStats?: {                   // City/state birth statistics for "Birth in {City}: By the Numbers" section
    cesareanRate?: number;          // Percentage (e.g. 34.5) — NO % sign, template adds it
    maternalMortalityRate?: number; // Raw number (e.g. 28.2) — NO units, template shows "per 100,000 live births"
    homeBirthRate?: number;         // Percentage (e.g. 1.5) — NO % sign, template adds it
    birthCenterBirthRate?: number;  // Percentage (e.g. 0.5) — NO % sign, template adds it
    dataYear?: number;             // Year the data was collected (e.g. 2023)
    dataSource?: string;           // Source attribution (e.g. "CDC NCHS, National Vital Statistics System")
  };
  postpartumSection?: string;      // City-specific postpartum care provider section (H2 + paragraph, \n\n separated, HTML allowed)
  providerReviewSection?: string;  // City-specific provider review / comparison section (H2 + paragraph, \n\n separated, HTML allowed)
}

